module roller_coaster_optimization(\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] N,\n    input [31:0] coeff0,\n    input [31:0] coeff1,\n    input [31:0] coeff2,\n    input [31:0] coeff3,\n    input [6:0] T,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] LOAD_COEFFS   = 3'd1;\n    localparam [2:0] CLEAR_DP      = 3'd2;\n    localparam [2:0] PROC_COASTER  = 3'd3;\n    localparam [2:0] PROC_RIDE     = 3'd4;\n    localparam [2:0] UPDATE_DP     = 3'd5;\n    localparam [2:0] FINISH        = 3'd6;\n    \n    reg [2:0] current_state, next_state;\n    \n    // Coefficients storage\n    reg [11:0] a [0:3];\n    reg [11:0] b [0:3];\n    reg [7:0]  tm [0:3];  // 't' renamed to avoid conflict\n    \n    // DP array memory (127 elements)\n    reg [15:0] dp [0:127];\n    \n    // Counters and indices\n    reg [1:0]  coaster_idx;\n    reg [4:0]  ride_count;\n    reg [6:0]  time_idx;\n    reg [15:0] cycle_counter;\n    \n    // Internal calculation registers\n    reg [15:0] fun_value;\n    reg [9:0]  time_needed;  // max 31*255 = 7905 -> 13 bits needed\n    reg [15:0] temp_dp_value;\n    \n    // Cycle limit parameter\n    localparam [15:0] MAX_CYCLES = 16'd5000;\n\n    // FSM main control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= IDLE;\n            cycle_counter <= 16'd0;\n            done <= 1'b0;\n            result <= 16'd0;\n            coaster_idx <= 2'd0;\n            ride_count <= 5'd0;\n            time_idx <= 7'd0;\n            \n            // Clear coefficients\n            for (integer i = 0; i < 4; i = i + 1) begin\n                a[i] <= 12'd0;\n                b[i] <= 12'd0;\n                tm[i] <= 8'd0;\n            end\n            \n            // Clear DP array\n            for (integer j = 0; j < 128; j = j + 1) begin\n                dp[j] <= 16'd0;\n            end\n        end else begin\n            cycle_counter <= cycle_counter + 16'd1;\n            current_state <= next_state;\n            \n            case (current_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 16'd0;\n                    cycle_counter <= 16'd0;\n                    if (start) begin\n                        next_state <= LOAD_COEFFS;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n                \n                LOAD_COEFFS: begin\n                    // Load active coefficients based on N\n                    a[0] <= coeff0[11:0];\n                    b[0] <= coeff0[23:12];\n                    tm[0] <= coeff0[31:24];\n                    \n                    if (N >= 2'd1) begin\n                        a[1] <= coeff1[11:0];\n                        b[1] <= coeff1[23:12];\n                        tm[1] <= coeff1[31:24];\n                    end\n                    \n                    if (N >= 2'd2) begin\n                        a[2] <= coeff2[11:0];\n                        b[2] <= coeff2[23:12];\n                        tm[2] <= coeff2[31:24];\n                    end\n                    \n                    if (N >= 2'd3) begin\n                        a[3] <= coeff3[11:0];\n                        b[3] <= coeff3[23:12];\n                        tm[3] <= coeff3[31:24];\n                    end\n                    \n                    coaster_idx <= 2'd0;\n                    next_state <= CLEAR_DP;\n                end\n                \n                CLEAR_DP: begin\n                    // Initialize DP array to 0\n                    for (integer j = 0; j < 128; j = j + 1) begin\n                        dp[j] <= 16'd0;\n                    end\n                    coaster_idx <= 2'd0;\n                    next_state <= PROC_COASTER;\n                end\n                \n                PROC_COASTER: begin\n                    ride_count <= 5'd1;\n                    time_idx <= T;\n                    \n                    if (coaster_idx >= N) begin\n                        next_state <= FINISH;\n                    end else begin\n                        next_state <= PROC_RIDE;\n                    end\n                end\n                \n                PROC_RIDE: begin\n                    ride_count <= ride_count + 5'd1;\n                    \n                    // Calculate fun_value = a - (k-1)^2 * b\n                    fun_value <= a[coaster_idx] - (ride_count * ride_count - 1'b1) * b[coaster_idx];\n                    \n                    // Calculate time_needed = k * t\n                    time_needed <= ride_count * tm[coaster_idx];\n                    \n                    // Move to UPDATE_DP if time_needed <= T and fun_value > 0\n                    if (time_needed <= {2'b00, T} && fun_value > 16'd0) begin\n                        next_state <= UPDATE_DP;\n                    end else if (ride_count == 5'd31) begin\n                        coaster_idx <= coaster_idx + 2'd1;\n                        next_state <= PROC_COASTER;\n                    end else begin\n                        next_state <= PROC_RIDE;\n                    end\n                end\n                \n                UPDATE_DP: begin\n                    if (time_idx >= time_needed[6:0]) begin\n                        temp_dp_value <= dp[time_idx - time_needed[6:0]] + fun_value;\n                        if (temp_dp_value > dp[time_idx]) begin\n                            dp[time_idx] <= temp_dp_value;\n                        end\n                        time_idx <= time_idx - 7'd1;\n                        next_state <= UPDATE_DP;\n                    end else begin\n                        if (ride_count == 5'd31) begin\n                            coaster_idx <= coaster_idx + 2'd1;\n                            next_state <= PROC_COASTER;\n                        end else begin\n                            next_state <= PROC_RIDE;\n                        end\n                    end\n                end\n                \n                FINISH: begin\n                    result <= dp[T];\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: begin\n                    next_state <= IDLE;\n                end\n            endcase\n            \n            // Timeout protection\n            if (cycle_counter >= MAX_CYCLES) begin\n                next_state <= FINISH;\n            end\n        end\n    end\nendmodule